impl Document {
    pub(crate) fn compare_bsw_composition_timing(
        &self,
        other: &Document,
        a: &BswCompositionTiming,
        b: &BswCompositionTiming,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_bsw_module_timing(
        &self,
        other: &Document,
        a: &BswModuleTiming,
        b: &BswModuleTiming,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_ecu_timing(
        &self,
        other: &Document,
        a: &EcuTiming,
        b: &EcuTiming,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_swc_timing(
        &self,
        other: &Document,
        a: &SwcTiming,
        b: &SwcTiming,
        path: &str,
    ) -> Result<(), String> {
        self.compare_timing_extension(other, a.base(), b.base(), path)?;
        if a.get_behavior_ref() != b.get_behavior_ref() {
            return Err(format!("{path}: BEHAVIOR_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_system_timing(
        &self,
        _other: &Document,
        a: &SystemTiming,
        b: &SystemTiming,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_timing_extension(
        &self,
        other: &Document,
        a: &TimingExtension,
        b: &TimingExtension,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        let list_a = a.get_timing_clocks();
        let list_b = b.get_timing_clocks();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: TIMING_CLOCKS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.TIMING_CLOCKS[{index}] mismatch"));
            }
        }
        let list_a = a.get_timing_clock_sync_accuracies();
        let list_b = b.get_timing_clock_sync_accuracies();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: TIMING_CLOCK_SYNC_ACCURACIES length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.timing_clock_sync_accuracys.get(*x).ok_or_else(|| {
                format!("{path}.TIMING_CLOCK_SYNC_ACCURACIES[{index}]: id not found in own arena")
            })?;
            let y = other.timing_clock_sync_accuracys.get(*y).ok_or_else(|| {
                format!("{path}.TIMING_CLOCK_SYNC_ACCURACIES[{index}]: id not found in other arena")
            })?;
            self.compare_timing_clock_sync_accuracy(
                other,
                x,
                y,
                &format!("{path}.TIMING_CLOCK_SYNC_ACCURACIES[{index}]"),
            )?;
        }
        let list_a = a.get_timing_conditions();
        let list_b = b.get_timing_conditions();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: TIMING_CONDITIONS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.timing_conditions.get(*x).ok_or_else(|| {
                format!("{path}.TIMING_CONDITIONS[{index}]: id not found in own arena")
            })?;
            let y = other.timing_conditions.get(*y).ok_or_else(|| {
                format!("{path}.TIMING_CONDITIONS[{index}]: id not found in other arena")
            })?;
            self.compare_timing_condition(
                other,
                x,
                y,
                &format!("{path}.TIMING_CONDITIONS[{index}]"),
            )?;
        }
        let list_a = a.get_timing_descriptions();
        let list_b = b.get_timing_descriptions();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: TIMING_DESCRIPTIONS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.TIMING_DESCRIPTIONS[{index}] mismatch"));
            }
        }
        let list_a = a.get_timing_guarantees();
        let list_b = b.get_timing_guarantees();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: TIMING_GUARANTEES length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.TIMING_GUARANTEES[{index}] mismatch"));
            }
        }
        let list_a = a.get_timing_requirements();
        let list_b = b.get_timing_requirements();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: TIMING_REQUIREMENTS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.TIMING_REQUIREMENTS[{index}] mismatch"));
            }
        }
        if a.get_timing_resource() != b.get_timing_resource() {
            return Err(format!("{path}: TIMING_RESOURCE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_vfb_timing(
        &self,
        other: &Document,
        a: &VfbTiming,
        b: &VfbTiming,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        Ok(())
    }
}
